(2169590, 297648, 10848, '<td valign="top">Adorable baby! Great tones, soft effective lighting. Best so far. Good luck! 10</td>', 'Adorable baby! Great tones, soft effective lighting. Best so far. Good luck! 10', '2006-02-22 00:36:06.000000', NULL, 1),
(2169593, 298750, 1, '<td valign="top">The house looks great against the sky, but the foliage, taking up 50% of the image is a bit distracting.</td>', 'The house looks great against the sky, but the foliage, taking up 50% of the image is a bit distracting.', '2006-02-22 00:36:34.000000', NULL, 1),
(2169597, 297547, 12131, '<td valign="top">What an interesting eye view.  I like the clarity and the architecture, but the two people on the left are kind of distracting.</td>', 'What an interesting eye view.  I like the clarity and the architecture, but the two people on the left are kind of distracting.', '2006-02-22 00:37:15.000000', NULL, 1),
(2169602, 297477, 1, '<td valign="top">The crop may be a little too tight, I''d prefer to see the whole tongue.  As well, something softer than orange could''ve worked better.</td>', 'The crop may be a little too tight, I''d prefer to see the whole tongue.  As well, something softer than orange could''ve worked better.', '2006-02-22 00:37:29.000000', NULL, 1),
(2169603, 296803, 12131, '<td valign="top">Beautiful photo and beautiful frame.</td>', 'Beautiful photo and beautiful frame.', '2006-02-22 00:37:48.000000', NULL, 1),
