(2174831, 298913, 46294, '<td valign="top">I think the reflection above the left eye is doing the picture no good.</td>', 'I think the reflection above the left eye is doing the picture no good.', '2006-02-23 02:37:22.000000', NULL, 1),
(2174832, 296649, 46294, '<td valign="top">Lovely eyes. A little too much softfocus.</td>', 'Lovely eyes. A little too much softfocus.', '2006-02-23 02:37:54.000000', NULL, 1),
