INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2175612, 298328, 43753, '<td valign="top">I think the composition might have been a little stronger had you pulled back the screen on both sides to serve as a sort of frame to the fire. Your exposure is great.</td>', 'I think the composition might have been a little stronger had you pulled back the screen on both sides to serve as a sort of frame to the fire. Your exposure is great.', '2006-02-23 10:59:19.000000', NULL, 1),
(2175613, 296232, 43753, '<td valign="top">Beautiful capture. I love the rays cascading down. Well seen!!</td>', 'Beautiful capture. I love the rays cascading down. Well seen!!', '2006-02-23 11:00:16.000000', NULL, 1),
(2175614, 298253, 43753, '<td valign="top">Simple composition with strong contrast in the details.</td>', 'Simple composition with strong contrast in the details.', '2006-02-23 11:00:48.000000', NULL, 1),
(2175620, 297695, 43753, '<td valign="top">Nice composition, but would crop a little more on the left to bring her eye into where the upper and left third lines intersect. I love the way the shadows play across her face, shoulder, and knee.</td>', 'Nice composition, but would crop a little more on the left to bring her eye into where the upper and left third lines intersect. I love the way the shadows play across her face, shoulder, and knee.', '2006-02-23 11:02:36.000000', NULL, 1),
(2175621, 297598, 43753, '<td valign="top">Beautiful tones and nice detail.</td>', 'Beautiful tones and nice detail.', '2006-02-23 11:02:57.000000', NULL, 1),
(2175622, 298612, 43753, '<td valign="top">Great perspective and DOF. The lighter parts of the mimage seem a little too bright. The tones elsewhere are very pleasing.</td>', 'Great perspective and DOF. The lighter parts of the mimage seem a little too bright. The tones elsewhere are very pleasing.', '2006-02-23 11:03:48.000000', NULL, 1),
(2175624, 296487, 43753, '<td valign="top">Great photojournalistic capture. I live the subject and composition. Wonderful shot!</td>', 'Great photojournalistic capture. I live the subject and composition. Wonderful shot!', '2006-02-23 11:04:14.000000', NULL, 1),
(2175625, 296755, 43753, '<td valign="top">Man, you nailed the lighting here. I love the textures in the fur and whiskers. The tonal range is excellent. Well done!</td>', 'Man, you nailed the lighting here. I love the textures in the fur and whiskers. The tonal range is excellent. Well done!', '2006-02-23 11:04:46.000000', NULL, 1),
(2175626, 296981, 43753, '<td valign="top">Excellent use of line. Love the entire composition. Contrast is great too.</td>', 'Excellent use of line. Love the entire composition. Contrast is great too.', '2006-02-23 11:05:16.000000', NULL, 1),
(2175634, 297010, 43753, '<td valign="top">Sweet! Like they are actually posing for you. I think a crop right around their heads would make a stronger composition in that it would draw the eye to the synchronization of the profiles.</td>', 'Sweet! Like they are actually posing for you. I think a crop right around their heads would make a stronger composition in that it would draw the eye to the synchronization of the profiles.', '2006-02-23 11:07:49.000000', NULL, 1),
