(2177273, 298526, 33361, '<td valign="top">too centered</td>', 'too centered', '2006-02-23 20:47:18.000000', NULL, 1),
(2177275, 298530, 35602, '<td valign="top">Well, here is my first 10 score.  Absolutely wonderful tones and reflection. Love the play of the water on the crane.  Gorgeous, and a fav.</td>', 'Well, here is my first 10 score.  Absolutely wonderful tones and reflection. Love the play of the water on the crane.  Gorgeous, and a fav.', '2006-02-23 20:47:27.000000', NULL, 1),
(2177277, 296080, 41675, '<td valign="top">I don''t mind your duotone - it''s kind of refreshing from all the black and whites I''ve seen. Something about the composition though..for me at least, I wish there was some other element to make it a bit more interesting.</td>', 'I don''t mind your duotone - it''s kind of refreshing from all the black and whites I''ve seen. Something about the composition though..for me at least, I wish there was some other element to make it a bit more interesting.', '2006-02-23 20:48:05.000000', NULL, 1),
(2177280, 298544, 41675, '<td valign="top">Nice, clean, crisp floral image. Good lighting, composition and duotone works well.</td>', 'Nice, clean, crisp floral image. Good lighting, composition and duotone works well.', '2006-02-23 20:48:49.000000', NULL, 1),
