(2189882, 298741, 19944, '<td valign="top">To me, this doesn''t really fit into the "spirit" of the Duotone challenge.  Otherwise, very nice colors and silhouette.</td>', 'To me, this doesn''t really fit into the "spirit" of the Duotone challenge.  Otherwise, very nice colors and silhouette.', '2006-02-28 14:00:52.000000', NULL, 1),
(2189884, 298901, 19944, '<td valign="top">What ever effect was applied, I think it ruins the photo.  I know the duotone has beenapplied, but it just doesn''t work for me.</td>', 'What ever effect was applied, I think it ruins the photo.  I know the duotone has beenapplied, but it just doesn''t work for me.', '2006-02-28 14:01:58.000000', NULL, 1),
(2189887, 298182, 19944, '<td valign="top">A very nice bug picture, but it doesn''t really fit the "spirit" of the Doutone category.</td>', 'A very nice bug picture, but it doesn''t really fit the "spirit" of the Doutone category.', '2006-02-28 14:02:05.000000', NULL, 1),
