(2189895, 298416, 19944, '<td valign="top">Sharp, nice tone, but nothing of any real interst to me.</td>', 'Sharp, nice tone, but nothing of any real interst to me.', '2006-02-28 14:06:15.000000', NULL, 1),
(2189899, 297254, 19944, '<td valign="top">Something looks weird along all of your edges.  Not sure what it is.</td>', 'Something looks weird along all of your edges.  Not sure what it is.', '2006-02-28 14:06:56.000000', NULL, 1),
(2189900, 298896, 19944, '<td valign="top">to me, it''s too noisy and the light is really harsh</td>', 'to me, it''s too noisy and the light is really harsh', '2006-02-28 14:07:42.000000', NULL, 1),
(2189902, 297519, 13982, '<td valign="top">why did you make this so small?</td>', 'why did you make this so small?', '2006-02-28 14:08:21.000000', NULL, 1),
