(2189905, 296917, 19944, '<td valign="top">I really like the high-key effect.  This is excellent</td>', 'I really like the high-key effect.  This is excellent', '2006-02-28 14:08:54.000000', NULL, 1),
(2189906, 296459, 19944, '<td valign="top">I usually like color in flower photos.  There is none needed here.  This is simply spectacular.  It just so sharp.  Congratulations.</td>', 'I usually like color in flower photos.  There is none needed here.  This is simply spectacular.  It just so sharp.  Congratulations.', '2006-02-28 14:09:09.000000', NULL, 1),
(2189928, 297933, 48545, '<td valign="top">Great photo, lighting and tonal balance is pretty much perfect.  So much more interesting with the man in the image.  Nice choice of duotone colour and I don''t think I''ve ever seen a border more befitting an image than this one :)</td>', 'Great photo, lighting and tonal balance is pretty much perfect.  So much more interesting with the man in the image.  Nice choice of duotone colour and I don''t think I''ve ever seen a border more befitting an image than this one :)', '2006-02-28 14:31:11.000000', NULL, 1),
(2189931, 298989, 48545, '<td valign="top">Lovely duotone colour and nice intense picture, you can almost feel the wet nose!</td>', 'Lovely duotone colour and nice intense picture, you can almost feel the wet nose!', '2006-02-28 14:31:59.000000', NULL, 1),
(2189933, 296628, 24486, '<td valign="top">Perfect execution. This is really excellant.</td>', 'Perfect execution. This is really excellant.', '2006-02-28 14:34:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2189941, 297114, 53132, '<td valign="top">Really interesting shot, I like it, particularly your decision to set the point of focus further back than the fron leaf; it dfeinitely makes you appreciate the whole shot.</td>', 'Really interesting shot, I like it, particularly your decision to set the point of focus further back than the fron leaf; it dfeinitely makes you appreciate the whole shot.', '2006-02-28 14:42:09.000000', NULL, 1),
