(2189948, 298962, 53132, '<td valign="top">This shot is fantastic, a little distracting but brilliant. I''m very new to photography, how did you achieve this effect?</td>', 'This shot is fantastic, a little distracting but brilliant. I''m very new to photography, how did you achieve this effect?', '2006-02-28 14:48:43.000000', NULL, 1),
(2189949, 298138, 16046, '<td valign="top">Nice detail, angle works for me</td>', 'Nice detail, angle works for me', '2006-02-28 14:49:37.000000', NULL, 1),
