INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2190907, 296593, 41337, '<td valign="top">Color is fantastic. Not crazy about the square crop.</td>', 'Color is fantastic. Not crazy about the square crop.', '2006-02-28 22:53:58.000000', NULL, 1),
(2190911, 298455, 37961, '<td valign="top">Oh man....this has got to ribbon. Enchanting and so darling. I love bunnies. 10.</td>', 'Oh man....this has got to ribbon. Enchanting and so darling. I love bunnies. 10.', '2006-02-28 22:55:59.000000', NULL, 1),
(2190915, 298426, 40484, '<td valign="top">maybe a slight rotation to the right of the whole image would improve presentation. I like the perspective looking down at the old buildings with the smoke rising. Looks like a cold morning.</td>', 'maybe a slight rotation to the right of the whole image would improve presentation. I like the perspective looking down at the old buildings with the smoke rising. Looks like a cold morning.', '2006-02-28 22:56:53.000000', NULL, 1),
(2190917, 296973, 15711, '<td valign="top">WOw - this guy surely jumps out at you.  The high contrast really works with the sepia. Great detail with the whiskers.</td>', 'WOw - this guy surely jumps out at you.  The high contrast really works with the sepia. Great detail with the whiskers.', '2006-02-28 22:59:12.000000', NULL, 1),
(2190920, 298468, 41337, '<td valign="top">That bird really adds depth and scale to the shot as well as the lines that lead the eyes upward. Nice photo. Bumping up.</td>', 'That bird really adds depth and scale to the shot as well as the lines that lead the eyes upward. Nice photo. Bumping up.', '2006-02-28 23:01:07.000000', NULL, 1),
(2190921, 296393, 15711, '<td valign="top">Really good.  I like the contrast of the figure amidst the dirty debris of the old buildling. 9</td>', 'Really good.  I like the contrast of the figure amidst the dirty debris of the old buildling. 9', '2006-02-28 23:01:19.000000', NULL, 1),
(2190923, 297929, 31005, '<td valign="top">lots of dust on your sensor!  I had that happen too many times.</td>', 'lots of dust on your sensor!  I had that happen too many times.', '2006-02-28 23:01:38.000000', NULL, 1),
(2190925, 297220, 41337, '<td valign="top">Nice contrast. Not sure why the photo needed to be validated.</td>', 'Nice contrast. Not sure why the photo needed to be validated.', '2006-02-28 23:02:25.000000', NULL, 1),
(2190926, 296083, 15711, '<td valign="top">Interesting subject matter.  I like the way you did it.  Literally an out of body experience!!! 8</td>', 'Interesting subject matter.  I like the way you did it.  Literally an out of body experience!!! 8', '2006-02-28 23:02:31.000000', NULL, 1),
(2190928, 296808, 15711, '<td valign="top">The little sparkle on the bottom of the droplet is really striking.</td>', 'The little sparkle on the bottom of the droplet is really striking.', '2006-02-28 23:03:54.000000', NULL, 1),
(2190930, 296484, 15711, '<td valign="top">Absolutely stunning. Perfect lighting and detail.  Beautiful. 10</td>', 'Absolutely stunning. Perfect lighting and detail.  Beautiful. 10', '2006-02-28 23:04:11.000000', NULL, 1),
(2190931, 298647, 46937, '<td valign="top">I really like this, its unique</td>', 'I really like this, its unique', '2006-02-28 23:04:40.000000', NULL, 1),
