INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2192550, 297408, 15266, '<td valign="top">This got a 5.3???  what''s up with voters lately?  This image clearly deserved a better score - its a lovely image.</td>', 'This got a 5.3???  what''s up with voters lately?  This image clearly deserved a better score - its a lovely image.', '2006-03-01 08:57:20.000000', NULL, 0),
(2192552, 298892, 50695, '<td valign="top">wonderful portrait. I made you a favorite photographer because I always end up scoring your pictures high.</td>', 'wonderful portrait. I made you a favorite photographer because I always end up scoring your pictures high.', '2006-03-01 08:57:52.000000', NULL, 0),
(2192553, 296864, 2716, '<td valign="top">orbs!!!</td>', 'orbs!!!', '2006-03-01 08:57:55.000000', NULL, 0),
(2192564, 297261, 49581, '<td valign="top">Hi DottieD,<br/> <br/>Sorry you didn''t get ANY comments on this pic, I''m just a beginner but I''ll try to add my own thoughts.<br/> <br/>First of, I don''t think this was the best picture for the Duotone challenge, as I think the picture would have held up better under full colour.<br/> <br/>The backlighting has really spoilt the picture making the foreground very dark. Either the picture needs to be recomposed to have the light coming from the right direction or some kind of fill-light needs to be used in the foreground.<br/> <br/>With regards to composition the diagonal line of the drain adds to the composition but cutting out half of the fireman and fire extinguisher detracts from it. The background with the bin and cable also detract from the main image, a shallower DOF to blur those out may have helped.<br/> <br/>HTH<br/>Bluenova</td>', 'Hi DottieD, Sorry you didn''t get ANY comments on this pic, I''m just a beginner but I''ll try to add my own thoughts. First of, I don''t think this was the best picture for the Duotone challenge, as I think the picture would have held up better under full colour. The backlighting has really spoilt the picture making the foreground very dark. Either the picture needs to be recomposed to have the light coming from the right direction or some kind of fill-light needs to be used in the foreground. With regards to composition the diagonal line of the drain adds to the composition but cutting out half of the fireman and fire extinguisher detracts from it. The background with the bin and cable also detract from the main image, a shallower DOF to blur those out may have helped. HTHBluenova', '2006-03-01 09:01:22.000000', NULL, 0),
(2192565, 298714, 50695, '<td valign="top">I don''t know why such a striking photo didn''t score higher. I gave you an 8.</td>', 'I don''t know why such a striking photo didn''t score higher. I gave you an 8.', '2006-03-01 09:01:30.000000', NULL, 0),
(2192571, 297517, 43221, '<td valign="top">Keep up the good work and don''t give a damn to the placing; 182 out of 612? Cryin'' shame!</td>', 'Keep up the good work and don''t give a damn to the placing; 182 out of 612? Cryin'' shame!', '2006-03-01 09:03:21.000000', NULL, 0),
